-- Generated by `python -m lakehouse uc-sql` from config/pipeline.yaml. Do not edit by hand.
-- Members of `pii_readers` see raw values; everyone else sees the masked value.
USE CATALOG main;
USE SCHEMA silver;

CREATE OR REPLACE FUNCTION pii_mask_hash(v STRING)
  RETURNS STRING
  RETURN CASE WHEN is_account_group_member('pii_readers') THEN v ELSE sha2(concat(secret('lakehouse', 'pii-hash-salt'), lower(trim(v))), 256) END;

CREATE OR REPLACE FUNCTION pii_mask_mask_last4(v STRING)
  RETURNS STRING
  RETURN CASE WHEN is_account_group_member('pii_readers') THEN v ELSE concat(repeat('*', greatest(length(v) - 4, 0)), right(v, 4)) END;

CREATE OR REPLACE FUNCTION pii_mask_redact(v STRING)
  RETURNS STRING
  RETURN CASE WHEN is_account_group_member('pii_readers') THEN v ELSE '***' END;

CREATE OR REPLACE FUNCTION pii_mask_year_only(v DATE)
  RETURNS DATE
  RETURN CASE WHEN is_account_group_member('pii_readers') THEN v ELSE make_date(year(v), 1, 1) END;

ALTER TABLE customers ALTER COLUMN date_of_birth SET MASK pii_mask_year_only;
ALTER TABLE customers ALTER COLUMN email SET MASK pii_mask_hash;
ALTER TABLE customers ALTER COLUMN full_name SET MASK pii_mask_redact;
ALTER TABLE customers ALTER COLUMN phone SET MASK pii_mask_mask_last4;
